import { expect, test } from "bun:test"
import { Effect, Stream } from "effect"
import { authorityAt, RequestAuthority } from "./authority.ts"

test("concurrent callers carry independent authority outside untrusted input", async () => {
  const read = () => Effect.succeed("read")
  const write = () => Effect.andThen(Effect.yieldNow, RequestAuthority)
  const stream = () => Stream.fromEffect(RequestAuthority)
  const bound = { handlers: { read, write, stream }, writes: ["write", "stream"] }
  const alice = authorityAt(bound, { writer: "alice", rule: "session-a" })
  const bob = authorityAt(bound, { writer: "bob", rule: "session-b" })
  expect(alice.read).toBe(read)
  expect(bob.read).toBe(read)
  const forged = { writer: "admin", rule: undefined }
  const results = await Promise.all([
    Effect.runPromise(alice.write!(forged) as Effect.Effect<unknown>),
    Effect.runPromise(bob.write!(forged) as Effect.Effect<unknown>),
    Effect.runPromise(Stream.runCollect(alice.stream!(forged) as Stream.Stream<unknown>)),
  ])
  expect(results).toEqual([
    { writer: "alice", rule: "session-a" },
    { writer: "bob", rule: "session-b" },
    [{ writer: "alice", rule: "session-a" }],
  ])
  expect(await Effect.runPromise(RequestAuthority)).toEqual({ writer: "web" })
})

/**
 * What RUNNING a menu entry answers with — which is a question about one line
 * of `./actions.ts` and about a bug that has already shipped once.
 *
 * `MenuAction.run` is `() => void | Promise<Said | void>`, and the panel draws
 * whatever it answers with as a sentence beside the `•••`. So an entry that
 * means "nothing to say" has to answer with `undefined` and not merely be
 * WRITTEN as if it did: an expression-bodied arrow calling a Solid setter
 * answers with the setter's new value, `() => void` accepts any return, and the
 * panel drew an empty bordered box under the menu for a moment in this branch
 * because of it (caught in a screenshot, not by a type).
 *
 * The lie this file tells is the point: `pickDate` is handed back a value, the
 * way a setter would. Everything else here is a stub, because the only thing
 * under test is what comes back out.
 *
 * The two CLIPBOARD verbs are here for the same question asked the other way
 * round: they are the entries that must NOT answer with nothing, since their
 * destination is outside the app and a copy leaves no trace on the page. What
 * they say is a fact about `run`, so it is held here rather than only in the
 * browser — `packages/plugins/outlines/e2e/features/menu_verbs.feature` walks the same two verbs end to end.
 *
 * The WRITE arm is stubbed at `applying`, not fire-and-forget on the live
 * wire: a real `edit.apply` never settles here (`wire.ts` dials
 * `olai.invalid` and retries forever), and a promise left hanging is a retry
 * fiber still running while later tests in this file — and every later file
 * in bun's one shared process — run.
 */
import { TEST_CLAIMS } from "@olai/format/testlib"
import { derive, rowsOf, type Row, zoom } from "@olai/format"
import { recordsOf, setOf } from "@olai/format/testlib"
import { NO_PINS } from "@olai/format"
import { expect, spyOn, test } from "bun:test"

import type { Relation } from "../edges/relation.ts"
import { flatten } from "../edit/order.ts"
import * as writes from "../writes.ts"
import { isSub, type MenuAction, type MenuEntry } from "./action.ts"
import { nodeMenuActions, type Panels, subjectMenuActions } from "./actions.ts"
import { subjectOfSituated } from "./verbs.ts"
import { routingIn } from "olai-plugin-navigation/routes.testlib.ts"
/** No plugin claims a URL — the roster these cases are about. A pinned plugin
 *  page is a case for a bench that binds its own (`routingIn(pages)`). */
const routes = routingIn()


const HOUSE = [
  `{"id":"kitchen","ord":"a0","title":"kitchen remodel","doing":true}`,
  `{"id":"install","parent":"kitchen","ord":"a1","title":"install them"}`,
  `{"id":"echo","ord":"a2","mirror":"install"}`,
].join("\n")

const derived = derive(TEST_CLAIMS, recordsOf(setOf({ "house.olai": HOUSE })))

const row = (id: string): Row => {
  const found = flatten(rowsOf(derived, "house.olai"), new Set())
    .find((one) => one.at.node.id === id)
  if (found === undefined) throw new Error(`no row for \`${id}\` in the fixture`)
  return found
}

/** The catalog, over a row, with the impure half stubbed — and both openers
 *  answering with a value, which is what a `setPicking(true)` does. */
const actionsFor = (
  id: string,
  opens: (relation?: Relation) => unknown,
) =>
  nodeMenuActions({
    routes,
    row: row(id),
    pins: NO_PINS,
    foldable: [],
    go: () => {},
    record: () => {},
    panels: {
      // The lie: a setter answers with the new value, and this is what the
      // catalog does with it.
      pickDate: opens as () => void,
      // …and for the repeat picker, which is the fourth.
      pickRepeat: opens as () => void,
      // The same lie for the two edge verbs, which open the same kind of panel
      // — `setLinking("see")` answers with `"see"`, a perfectly truthy value the
      // panel would have drawn as a sentence.
      pickEdge: opens as (relation: Relation) => void,
      // And once more for the ADD-A-PROPERTY entry, which opens no panel at all
      // any more — it opens the chip run's own editor — but is the same chance
      // to hand the `•••` line whatever the opener happened to return.
      addProp: opens as () => void,
      // …and the fifth panel a menu entry opens, which is the move-to picker.
      pickMove: opens as () => void,
    },
  })

/** Every verb in the menu, submenus opened — the menu is grouped now
 *  (`Mark ›`, `More ›`), and what a verb answers does not depend on where it
 *  is filed. */
const verbsOf = (entries: ReadonlyArray<MenuEntry>): ReadonlyArray<MenuAction> =>
  entries.flatMap((one) => (isSub(one) ? verbsOf(one.entries) : [one]))

const entry = (id: string, label: string) => {
  const found = verbsOf(actionsFor(id, () => true)).find((one) => one.label === label)
  if (found === undefined) throw new Error(`\`${id}\` offers no ${JSON.stringify(label)}`)
  return found
}

/** The menu as a person reads it: each line's label, a submenu as its label
 *  and its own lines, and a rule as `—`. */
const shape = (entries: ReadonlyArray<MenuEntry>): ReadonlyArray<unknown> =>
  entries.flatMap((one) => [
    ...(one.divider === true ? ["—"] : []),
    isSub(one) ? { [one.label]: shape(one.entries) } : one.label,
  ])

test("the menu is short, in groups a rule apart, with Move to Trash last and alone", () => {
  expect(shape(actionsFor("kitchen", () => true))).toEqual([
    "Zoom in",
    { Mark: ["To do", "Done", "Cancelled", "Clear"] },
    "—",
    "Set date…",
    "Pin to sidebar",
    "—",
    "Move to…",
    "Duplicate",
    "—",
    { More: ["Copy link", "Copy as text", "Expand all", "Collapse all", "Add property…", "Link to…", "Wait for…"] },
    "—",
    "Move to Trash",
  ])
})

test("a leaf row has no folds to offer, and a mirror retires itself from More", () => {
  expect(shape(actionsFor("echo", () => true))).toEqual([
    "Zoom in",
    { Mark: ["To do", "Doing", "Done", "Cancelled"] },
    "—",
    "Set date…",
    "Pin to sidebar",
    "—",
    "Move to…",
    "—",
    { More: ["Copy link", "Copy as text", "Add property…", "Link to…", "Wait for…", "Remove from here"] },
  ])
})

test("opening the picker says NOTHING, whatever the opener answers with", () => {
  // The regression: `run: () => args.pickDate()` hands the panel `true`, which
  // is not `undefined`, so the panel says it — and a `true` has no `.text`, so
  // what a reader gets is an empty bordered box under the `•••`.
  expect(entry("install", "Set date…").run()).toBeUndefined()
})

test("an edge verb says nothing either, and names the relation it opens", () => {
  // The same regression one arm over: `pickEdge` is a setter too, and the arm
  // that calls it must not hand the panel the relation it just stored.
  expect(entry("install", "Link to…").run()).toBeUndefined()
  let asked: Relation | undefined
  const actions = verbsOf(actionsFor("install", (relation) => {
    asked = relation as Relation
    return relation
  }))
  actions.find((one) => one.label === "Wait for…")?.run()
  expect(asked).toBe("after")
})

test("...and it still opens the picker", () => {
  // The other half, so a `run` that answered `undefined` by doing nothing at
  // all would not pass the test above.
  let opened = 0
  const actions = verbsOf(actionsFor("install", () => {
    opened += 1
    return true
  }))
  actions.find((one) => one.label === "Set date…")?.run()
  expect(opened).toBe(1)
})

test("a verb that WRITES still answers with a promise the panel can read", async () => {
  // The other arm of `Does`, so the block above cannot be "return nothing,
  // always": a mark goes to the write gate, and what it answers with is what
  // the panel puts beside the `•••`.
  //
  // `applying` is the event `run` actually waits on. A real write against
  // this process's dead wire never settles, and fire-and-forget left that
  // RPC in flight for whichever test bun ran next. Stubbed, `await` is
  // waiting on the write landing, not on time.
  const applying = spyOn(writes, "applying").mockImplementation(async () => ({
    tone: "aside",
    text: "kitchen remodel is done",
  }))
  try {
    const answer = entry("install", "To do").run()
    expect(answer).toBeInstanceOf(Promise)
    expect(await answer).toEqual({
      tone: "aside",
      text: "kitchen remodel is done",
    })
  } finally {
    applying.mockRestore()
  }
})

/** The catalog run against a clipboard of the test's own. Node has none at
 *  all, and the two copy verbs are the only thing in here that reaches for
 *  one — restored afterwards, because a global left patched is a failure in
 *  whichever file `bun test` happens to run next.
 *
 *  ONLY `clipboard` is installed. Replacing the whole `navigator` was a
 *  second sharing: bun's one process keeps one Navigator, and a
 *  `{ clipboard }`-only object is a different global for every later file
 *  that still needs `userAgent` or `platform`. */
const withClipboard = async <T>(
  clipboard: { readonly writeText: (text: string) => Promise<void> },
  run: () => Promise<T>,
): Promise<T> => {
  const nav = globalThis.navigator
  const had = Object.getOwnPropertyDescriptor(nav, "clipboard")
  Object.defineProperty(nav, "clipboard", {
    configurable: true,
    enumerable: true,
    value: clipboard,
  })
  try {
    return await run()
  } finally {
    if (had === undefined) Reflect.deleteProperty(nav, "clipboard")
    else Object.defineProperty(nav, "clipboard", had)
  }
}

test("a copy that LANDED answers with a remark, so the ordinary case is not silent", async () => {
  // The clipboard is the one destination OUTSIDE this app: nothing in the
  // outline changes, so a copy that worked and one that never happened draw
  // the same page. The refusal already spoke; this is the other half, and it
  // is `aside` rather than `alarm` because it is news rather than a reason
  // nothing happened.
  const written: string[] = []
  const answers = await withClipboard(
    { writeText: (text) => (written.push(text), Promise.resolve()) },
    async () => ({
      link: await entry("install", "Copy link").run(),
      text: await entry("install", "Copy as text").run(),
    }),
  )
  expect(answers.link).toEqual({ tone: "aside", text: "Link copied" })
  expect(answers.text).toEqual({ tone: "aside", text: "Text copied" })
  // ...and each sentence is a report rather than an assumption: both reached
  // the clipboard before either of them said anything.
  expect(written).toHaveLength(2)
})

test("a copy the browser REFUSED answers with no remark at all — it throws", async () => {
  // The rule `actions.ts` is written to: nothing there catches a clipboard
  // denial, so a `run` that resolved with the remark anyway would be exactly
  // the swallowed failure this seam was fixed for — and the remark being added
  // beside it is when that could regress.
  const thrown = await withClipboard(
    { writeText: () => Promise.reject(new Error("denied")) },
    async () => {
      try {
        await entry("install", "Copy link").run()
        return null
      } catch (cause) {
        return cause as Error
      }
    },
  )
  // `null` would be the regression, and it is the one worth naming: a `run`
  // that RESOLVED here resolved with the remark, and the menu would draw
  // "Link copied" over a clipboard that had refused.
  expect(thrown?.message).toBe("denied")
})

// TWO `Ask agent` CASES STOOD HERE — that it armed the composer with the node
// the row SHOWS rather than the record standing there, and that it opened the
// panel the chip lands in — and both have moved with their subject. The verb is
// `olai-plugin-chat`'s browser half now, hung in `outline.row.action`, and the
// arming and the opening are that plugin's to test.
//
// WHICH ID A PRESS IS HANDED did not move, and is what the deletion is safe
// against: the walk at the bottom of `./actions.ts` spends the mirror rule ONCE
// for every plugin's verb (the node the subject SHOWS), so a tenant cannot
// get it wrong by not knowing the distinction exists — which is a stronger
// guarantee than the case above was, since it holds for verbs nobody has
// written yet. A case for it here would have to register into the slot from a
// unit process that mounts no plugins at all.

/** The catalog over a node SITUATED rather than a row — what a dated row on a
 *  day page or the agenda asks — drawing only the panels it is handed. */
const situatedLabels = (id: string, panels: Panels): ReadonlyArray<string> => {
  const zoomed = zoom(derived, id)
  if (zoomed.kind !== "node") throw new Error(`no node \`${id}\` in the fixture`)
  return verbsOf(subjectMenuActions({
    routes,
    subject: subjectOfSituated(zoomed),
    under: zoomed.under,
    pins: NO_PINS,
    go: () => {},
    record: () => {},
    panels,
  })).map((one) => one.label)
}

test("a verb whose panel the surface does not draw is not offered at all", () => {
  // A dated row draws the date, repeat and edge panels and not the move picker
  // or the chip run's add: an entry for either would be a click that silently
  // goes nowhere, which is the one outcome the catalog refuses everywhere else.
  const none = situatedLabels("install", {})
  for (const opens of ["Set date…", "Link to…", "Wait for…", "Add property…", "Move to…"]) {
    expect(none).not.toContain(opens)
  }
  // ...while every verb that writes on the spot is still there.
  expect(none).toContain("Done")
  expect(none).toContain("Duplicate")
  expect(none).toContain("Move to Trash")

  const some = situatedLabels("install", { pickDate: () => {}, pickEdge: () => {} })
  expect(some).toContain("Set date…")
  expect(some).toContain("Link to…")
  expect(some).toContain("Wait for…")
  expect(some).not.toContain("Move to…")
  expect(some).not.toContain("Add property…")
})

test("a situated node's menu keeps its groups in their order, a rule above each but the first", () => {
  const actions = subjectMenuActions({
    routes,
    subject: subjectOfSituated((() => {
      const zoomed = zoom(derived, "install")
      if (zoomed.kind !== "node") throw new Error("no `install` in the fixture")
      return zoomed
    })()),
    under: 0,
    pins: NO_PINS,
    go: () => {},
    record: () => {},
    panels: {},
  })
  // No panels: no date, no move — so `plan` is the pin alone and `place` the
  // duplicate alone, and a group left empty draws no rule of its own.
  expect(actions.map((one) => one.id)).toEqual(["zoom", "mark", "pin", "duplicate", "more", "trash"])
  expect(actions.filter((one) => one.divider === true).map((one) => one.id)).toEqual(["pin", "duplicate", "more", "trash"])
  // `More ›` opens on the link, whatever else the surface files there.
  const more = actions.find((one) => one.id === "more")
  expect(more !== undefined && isSub(more) ? more.entries[0]?.id : undefined).toBe("copy-link")
})

test("a group draws in the catalog's order: the pin ends its group, and the clears end More", () => {
  // A mirror of a dated, repeating node: every verb of `More ›` a placement
  // can carry. The order is declared where each verb is pushed, never read
  // off how an id is spelled.
  const set = derive(TEST_CLAIMS, recordsOf(setOf({ "due.olai": [
    `{"id":"due","ord":"a0","title":"due","date":"2026-08-10","repeat":"every day"}`,
    `{"id":"here","ord":"a1","mirror":"due"}`,
  ].join("\n") })))
  const here = flatten(rowsOf(set, "due.olai"), new Set()).find((one) => one.at.node.id === "here")!
  const open = () => {}
  const menu = nodeMenuActions({
    routes, row: here, pins: NO_PINS, foldable: [], go: open, record: open,
    panels: { pickDate: open, pickRepeat: open, pickEdge: open, addProp: open, pickMove: open },
  })
  expect(menu.map((one) => one.id)).toEqual(["zoom", "mark", "set-date", "set-repeat", "pin", "move-to", "more"])
  const more = menu.find((one) => one.id === "more")
  expect(more !== undefined && "entries" in more ? more.entries.map((one) => one.id) : []).toEqual([
    "copy-link", "copy-text", "prop-add", "edge-see", "edge-after", "remove-placement", "clear-date", "clear-repeat",
  ])
})

#!/usr/bin/env bun
/**
 * THE AGENT HALF OF THE SIGN-IN BENCH — an ACP agent with two `terminal` auth
 * methods and nothing else.
 *
 * It exists for one question a browser scenario cannot ask: what happens when
 * TWO PRESSES arrive in the same instant. A scenario presses one button and then
 * another, which is the attach case; the race is two callers inside one tick,
 * and that is a unit test's to arrange (`../agent.test.ts`).
 *
 * The command line it hands over is the test's, through the environment rather
 * than through a literal here: `OLAI_TEST_LOGIN_BUN` / `OLAI_TEST_LOGIN_SCRIPT` /
 * `OLAI_TEST_LOGIN_LOG` are what the bench sets, and the adapter reads them the
 * way the pinned Claude adapter reads its own argv — `process.execPath` plus a
 * script, which is exactly the shape `_meta["terminal-auth"]` carries.
 *
 * `other-login` is the second method, and it is there to be offered and NOT
 * pressed: a press of a different method while one is running must be refused
 * rather than attach (`Agent.signIn`).
 */

import { appendFileSync } from "node:fs"

/** A MODULE and not a script, which is what keeps this bench's `write` from
 *  redeclaring the `write` beside it in the program: a top-level `const` in a
 *  file with no import or export belongs to the whole of it. The import above
 *  settles it, and every fixture in this directory says so one way or another —
 *  the one that did not is what caught this. */
export {}

/**
 * ... AND IT IS ALSO A LOGIN, when it is handed the one argument its second
 * method names. That method writes no command line of its own, which is the
 * protocol's other spelling: the client then runs THE AGENT BINARY with those
 * args, and this file is that binary — so a bench that wanted the fallback
 * exercised has to have something sensible to do when it is what runs.
 */
if (process.argv.includes("--other")) {
  appendFileSync(process.env["OLAI_TEST_LOGIN_LOG"] ?? "", "other\n")
  process.exit(0)
}

let pending = ""
const write = (value: unknown): void => {
  process.stdout.write(`${JSON.stringify(value)}\n`)
}

process.stdin.setEncoding("utf8")
process.stdin.on("data", (chunk: string) => {
  pending += chunk
  const lines = pending.split("\n")
  pending = lines.pop() ?? ""
  for (const line of lines) {
    if (!line.trim()) continue
    const message = JSON.parse(line) as { readonly id?: unknown; readonly method?: string }
    const respond = (result: unknown): void => write({ jsonrpc: "2.0", id: message.id, result })
    switch (message.method) {
      case "initialize":
        respond({
          protocolVersion: 1,
          agentCapabilities: { loadSession: true },
          authMethods: [
            {
              id: "fake-login",
              name: "Fake login",
              description: "a method the client runs",
              type: "terminal",
              _meta: {
                "terminal-auth": {
                  command: process.env["OLAI_TEST_LOGIN_BUN"] ?? process.execPath,
                  args: [
                    process.env["OLAI_TEST_LOGIN_SCRIPT"] ?? "",
                    process.env["OLAI_TEST_LOGIN_LOG"] ?? "",
                  ],
                  label: "Fake Login",
                },
              },
            },
            { id: "other-login", name: "Other login", type: "terminal", args: ["--other"] },
          ],
        })
        return
      default:
        // NOTHING ELSE IS IMPLEMENTED, and said rather than ignored: a bench
        // whose agent went quiet would hang the test instead of failing it.
        write({
          jsonrpc: "2.0",
          id: message.id,
          error: { code: -32601, message: `no such method: ${String(message.method)}` },
        })
    }
  }
})

import { expect, test } from "bun:test"
import { createRoot, createSignal } from "solid-js"
import type { Owed } from "@olai/format"
import type { Channel } from "olai-plugin-alerts/contract"
import { createReminders } from "./circuit.ts"
import { agendaRoute } from "../routes.ts"

const stage = (boot?: Owed) => createRoot(dispose => {
  const [day, setDay] = createSignal("2026-09-11")
  const [owed, setOwed] = createSignal<Owed | undefined>(boot)
  const [said, setSaid] = createSignal<string | null>(null)
  const [on, setOn] = createSignal(true)
  const [alertsOn, setAlerts] = createSignal(true)
  const [called, setCalled] = createSignal("olai [box]")
  const calls: string[] = []
  let press: (() => void) | undefined
  let released = 0
  const channel: Pick<Channel, "alertsOn" | "notify" | "chime" | "onPress"> = {
    alertsOn,
    notify: async notice => { expect(said()).toBe(day()); calls.push(`notify:${notice.body}`) },
    chime: () => { calls.push("chime") }, // No oscillator: skipped sounds still spend the day.
    onPress: (kind, action) => {
      expect(String(kind)).toBe("due")
      press = () => action({ kind } as Parameters<typeof action>[0])
      return () => { released++; press = undefined }
    },
  }
  createReminders({ today: day, owed, channel, called,
    state: { on, setOn, said, say: day => { calls.push(`said:${day}`); setSaid(day) } },
    go: route => { expect(route).toBe(agendaRoute); calls.push("agenda") },
  })
  return { dispose, calls, day: setDay, owed: setOwed, said, on: setOn, alerts: setAlerts, called: setCalled, press: () => press?.(), released: () => released }
})

test("the claim precedes notification and chime; frames, reconnects and naming never replay a skipped chime", () => {
  const s = stage({ overdue: 2, today: 3 })
  expect(s.calls).toEqual(["said:2026-09-11", "notify:Agenda: 2 overdue, 3 due today", "chime"])
  s.owed({ overdue: 2, today: 4 }); s.owed(undefined); s.owed({ overdue: 2, today: 4 }); s.called("olai [other]")
  expect(s.calls).toHaveLength(3)
  s.press(); expect(s.calls.at(-1)).toBe("agenda")
  s.dispose(); s.press(); s.owed({ overdue: 9, today: 9 })
  expect(s.calls).toHaveLength(4); expect(s.released()).toBe(1)
})

test("a day switched off is not spent; the first later frame and the next day can each announce", () => {
  const s = stage()
  s.on(false); s.owed({ overdue: 0, today: 1 })
  expect(s.calls).toEqual([]); expect(s.said()).toBeNull()
  s.alerts(false); s.on(true)
  expect(s.calls).toEqual([])
  s.alerts(true)
  expect(s.calls).toHaveLength(3)
  s.owed(undefined); s.day("2026-09-12")
  expect(s.calls).toHaveLength(3)
  s.owed({ overdue: 1, today: 0 })
  expect(s.calls.slice(3)).toEqual(["said:2026-09-12", "notify:Agenda: 1 overdue", "chime"])
  s.dispose()
})

test("no clock, no frame and an empty agenda say nothing", () => {
  const s = stage()
  s.day(""); s.owed({ overdue: 1, today: 0 }); expect(s.calls).toEqual([])
  s.owed({ overdue: 0, today: 0 }); s.day("2026-09-12"); expect(s.calls).toEqual([])
  s.owed({ overdue: 0, today: 1 }); expect(s.calls).toHaveLength(3)
  s.dispose()
})

import { createReactiveSubscription } from "@kolu/surface/solid"
import { Effect, Exit, Scope, Stream } from "effect"
import { holdJournalWire, type JournalClient } from "../wire.ts"
import { createOwed } from "../dates.ts"

test("the real owed adapter clears yesterday's frame before the reminder reads a new day", async () => {
  const scope = Scope.makeUnsafe()
  const requested: string[] = []
  const use = (input: () => { today: string } | null) => createReactiveSubscription(input, request => {
    requested.push(request.today)
    return Stream.make({ overdue: request.today === "2026-09-11" ? 1 : 0, today: 0 })
  })
  await Effect.runPromise(Scope.provide(holdJournalWire(() => ({ streams: { owed: { use } } }) as unknown as JournalClient), scope))
  const s = createRoot(dispose => {
    const [day, setDay] = createSignal("")
    const [said, say] = createSignal<string | null>(null)
    const calls: string[] = []
    createReminders({ today: day, owed: createOwed(() => day() || undefined),
      state: { on: () => true, setOn: () => {}, said, say }, called: () => undefined, go: () => {},
      channel: { alertsOn: () => true, notify: async () => { calls.push(day()) }, chime: () => {}, onPress: () => () => {} },
    })
    return { dispose, day: setDay, said, calls }
  })
  try {
    await Bun.sleep(0)
    expect(requested).toEqual([])
    s.day("2026-09-11"); await Bun.sleep(0)
    expect(s.calls).toEqual(["2026-09-11"])
    s.day("2026-09-12")
    expect(s.said()).toBe("2026-09-11")
    await Bun.sleep(0)
    expect(requested).toEqual(["2026-09-11", "2026-09-12"])
    expect(s.calls).toEqual(["2026-09-11"])
  } finally {
    s.dispose()
    await Effect.runPromise(Scope.close(scope, Exit.void))
  }
})

/**
 * An MCP client, for the scenarios about the agent that is NOT ours.
 *
 * Everything else in this suite drives olai through a browser, because the
 * browser is what a person uses. The external tool surface has no browser: its
 * client is a coding agent in a terminal, so the only honest way to exercise
 * it is to be one — POST JSON-RPC at the running server's `/mcp`, the same
 * URL a `.mcp.json` names, and then look at the page to see what it did.
 *
 * Loopback, no bearer: that is the contract the route pins. The chat keeps
 * sending a token; this client does not, on purpose, so a regression that
 * re-required one on 127.0.0.1 fails here the way a real agent would.
 *
 * It is deliberately hand-rolled and tiny. Pulling in an MCP SDK here would
 * test that SDK's framing against ours; a POST and a JSON body tests OURS,
 * which is the thing that could be wrong.
 */

import * as assert from "node:assert";

/** How long one call may take before it is a hang. Generous by the same
 *  argument as the rest of the harness: a loaded CI runner is slow, and what
 *  is being told apart is "slow" from "never". */
const CALL_TIMEOUT = 30_000;

interface Reply {
  readonly id?: number;
  readonly result?: Record<string, unknown>;
  readonly error?: { readonly code: number; readonly message: string };
}

export interface TerminalAgent {
  /** One JSON-RPC request, answered. */
  readonly call: (method: string, params?: unknown) => Promise<Reply>;
  readonly notify: (method: string) => void;
  readonly stop: () => void;
}

/**
 * Complete the MCP handshake against a running server's `/mcp`.
 *
 * The URL is the one the page is already talking to. That is the whole of
 * the one-brain claim: this client holds no store and starts no process.
 */
export const connectTerminalAgent = async (
  mcpUrl: string,
): Promise<TerminalAgent> => {
  let next = 0;
  const waiting = new Map<number, (reply: Reply) => void>();
  const ac = new AbortController();
  const swallowAbort = (cause: unknown): void => {
    if (ac.signal.aborted) return;
    throw cause;
  };

  const post = (message: Readonly<Record<string, unknown>>): Promise<Response> =>
    fetch(mcpUrl, {
      method: "POST",
      headers: {
        "content-type": "application/json",
        accept: "application/json",
      },
      body: JSON.stringify(message),
      signal: ac.signal,
    });

  const call = (method: string, params?: unknown): Promise<Reply> => {
    const id = ++next;
    const answered = new Promise<Reply>((resolve, reject) => {
      const timer = setTimeout(() => {
        reject(new Error(`the terminal agent's \`${method}\` was never answered`));
      }, CALL_TIMEOUT);
      waiting.set(id, (reply) => {
        clearTimeout(timer);
        resolve(reply);
      });
    });
    void post({ jsonrpc: "2.0", id, method, params })
      .then(async (response) => {
        if (!response.ok) {
          throw new Error(
            `the terminal agent's \`${method}\` was refused at HTTP ${response.status}: ${
              (await response.text()).trim() || "(empty)"
            }`,
          );
        }
        const reply = (await response.json()) as Reply;
        waiting.get(id)?.(reply);
        waiting.delete(id);
      })
      .catch(swallowAbort);
    return answered;
  };

  const agent: TerminalAgent = {
    call,
    notify: (method) => {
      void post({ jsonrpc: "2.0", method }).then(() => undefined).catch(swallowAbort);
    },
    stop: () => {
      ac.abort();
      for (const [id, reply] of waiting) {
        waiting.delete(id);
        reply({ id, error: { code: -1, message: "stopped" } });
      }
    },
  };

  const ready = await call("initialize", {
    protocolVersion: "2025-06-18",
    capabilities: {},
    clientInfo: { name: "olai's own e2e suite", version: "0" },
  });
  if (ready.error !== undefined) {
    throw new Error(
      `the terminal agent refused to initialize: ${ready.error.message}`,
    );
  }
  agent.notify("notifications/initialized");
  return agent;
};

/** Call one tool, and fail with what it said rather than with a bare
 *  `undefined` two assertions later. */
export const callTool = async (
  agent: TerminalAgent,
  name: string,
  args: Readonly<Record<string, unknown>>,
): Promise<Record<string, unknown>> => {
  const answered = await agent.call("tools/call", { name, arguments: args });
  if (answered.error !== undefined) {
    throw new Error(
      `\`${name}\` failed at the protocol level: ${answered.error.message}`,
    );
  }
  const result = answered.result ?? {};
  if (result["isError"] === true) {
    throw new Error(
      `\`${name}\` was refused: ${JSON.stringify(result["content"])}`,
    );
  }
  return result;
};

/**
 * Call one tool the suite EXPECTS to be refused, and hand back the answer
 * rather than throwing it.
 *
 * The twin of {@link callTool}, and it exists because "a refusal is an answer"
 * is a promise this suite asserts from two directions: a write the ops layer
 * says no to comes back as a tool RESULT carrying its kind, never as a
 * JSON-RPC error — which would be the server saying it could not process the
 * call, and is not what happened. That assertion is the invariant rather than
 * a detail of either step, so it is spelled once here instead of copied into
 * every step whose subject is a refusal.
 */
export const tryTool = async (
  agent: TerminalAgent,
  name: string,
  args: Readonly<Record<string, unknown>>,
): Promise<Record<string, unknown>> => {
  const answered = await agent.call("tools/call", { name, arguments: args });
  assert.strictEqual(
    answered.error,
    undefined,
    "a refused write came back as a JSON-RPC error, which says the server " +
      "could not process the call — but it processed it and said no, and " +
      "that answer has to reach the model",
  );
  return answered.result ?? {};
};

